using RadWareF1.Application.Contracts.Friends;

namespace RadWareF1.Application.Abstractions;

public interface IFriendService
{
    Task<IReadOnlyList<FriendResponse>> GetFriendsAsync(Guid currentUserId, CancellationToken cancellationToken);
    Task<AddFriendResponse> AddFriendAsync(Guid currentUserId, AddFriendRequest request, CancellationToken cancellationToken);
}

namespace RadWareF1.Application.Contracts.Friends;

public class AddFriendRequest
{
    public string Identifier { get; set; } = null!;
}

namespace RadWareF1.Application.Contracts.Friends;

public class AddFriendResponse
{
    public FriendResponse Friend { get; set; } = null!;
    public bool IsNewFriend { get; set; }
}

namespace RadWareF1.Application.Contracts.Friends;

public class FriendResponse
{
    public Guid UserId { get; set; }
    public string Email { get; set; } = null!;
    public DateTime AddedAtUtc { get; set; }
}

using Microsoft.EntityFrameworkCore;
using RadWareF1.Application.Abstractions;
using RadWareF1.Application.Contracts.Friends;
using RadWareF1.Domain;
using RadWareF1.Persistance;

namespace RadWareF1.Application.Services;

public class FriendService : IFriendService
{
    private readonly AppDbContext _dbContext;

    public FriendService(AppDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    public async Task<IReadOnlyList<FriendResponse>> GetFriendsAsync(Guid currentUserId, CancellationToken cancellationToken)
    {
        var friendships = await _dbContext.Friendships
            .AsNoTracking()
            .Where(x => x.UserAId == currentUserId || x.UserBId == currentUserId)
            .OrderByDescending(x => x.CreatedAtUtc)
            .Select(x => new
            {
                x.UserAId,
                x.UserBId,
                x.CreatedAtUtc
            })
            .ToListAsync(cancellationToken);

        if (friendships.Count == 0)
        {
            return Array.Empty<FriendResponse>();
        }

        var friendIds = friendships
            .Select(x => x.UserAId == currentUserId ? x.UserBId : x.UserAId)
            .ToArray();

        var usersById = await _dbContext.Users
            .AsNoTracking()
            .Where(x => friendIds.Contains(x.Id))
            .ToDictionaryAsync(x => x.Id, cancellationToken);

        return friendships
            .Select(x =>
            {
                var friendId = x.UserAId == currentUserId ? x.UserBId : x.UserAId;
                var friend = usersById[friendId];

                return new FriendResponse
                {
                    UserId = friend.Id,
                    Email = friend.Email,
                    AddedAtUtc = x.CreatedAtUtc
                };
            })
            .ToList();
    }

    public async Task<AddFriendResponse> AddFriendAsync(Guid currentUserId, AddFriendRequest request, CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(request.Identifier))
        {
            throw new InvalidOperationException("Please provide a user id or email.");
        }

        var identifier = request.Identifier.Trim();

        var targetUser = await ResolveUserAsync(identifier, cancellationToken);
        if (targetUser is null)
        {
            throw new KeyNotFoundException("User not found.");
        }

        if (targetUser.Id == currentUserId)
        {
            throw new InvalidOperationException("You cannot add yourself as a friend.");
        }

        var (userAId, userBId) = OrderPair(currentUserId, targetUser.Id);
        var existing = await _dbContext.Friendships
            .SingleOrDefaultAsync(x => x.UserAId == userAId && x.UserBId == userBId, cancellationToken);
        var created = false;

        if (existing is null)
        {
            existing = new Friendship
            {
                Id = Guid.NewGuid(),
                UserAId = userAId,
                UserBId = userBId,
                CreatedAtUtc = DateTime.UtcNow
            };

            _dbContext.Friendships.Add(existing);
            await _dbContext.SaveChangesAsync(cancellationToken);
            created = true;
        }

        return new AddFriendResponse
        {
            Friend = new FriendResponse
            {
                UserId = targetUser.Id,
                Email = targetUser.Email,
                AddedAtUtc = existing.CreatedAtUtc
            },
            IsNewFriend = created
        };
    }

    private async Task<User?> ResolveUserAsync(string identifier, CancellationToken cancellationToken)
    {
        if (Guid.TryParse(identifier, out var userId))
        {
            return await _dbContext.Users
                .SingleOrDefaultAsync(x => x.Id == userId, cancellationToken);
        }

        var normalizedEmail = identifier.ToLower();
        return await _dbContext.Users
            .SingleOrDefaultAsync(x => x.Email.ToLower() == normalizedEmail, cancellationToken);
    }

    private static (Guid UserAId, Guid UserBId) OrderPair(Guid first, Guid second)
    {
        return first.CompareTo(second) <= 0
            ? (first, second)
            : (second, first);
    }
}

using Microsoft.EntityFrameworkCore;
using RadWareF1.Application.Abstractions;
using RadWareF1.Application.Common;
using RadWareF1.Application.Contracts.Groups;
using RadWareF1.Application.Contracts.Groups.JoinGroup;
using RadWareF1.Domain;
using RadWareF1.Persistance;

namespace RadWareF1.Application.Services;

public class GroupService : IGroupService
{
    private readonly AppDbContext _dbContext;

    public GroupService(AppDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    public async Task<CreateGroupResponse> CreateAsync(
        Guid userId,
        CreateGroupRequest request,
        CancellationToken cancellationToken)
    {
        var joinCode = await GenerateUniqueJoinCodeAsync(cancellationToken);

        var group = new Group
        {
            Id = Guid.NewGuid(),
            Name = request.Name,
            Visibility = request.Visibility,
            JoinCode = joinCode,
            CreatedAtUtc = DateTime.UtcNow
        };

        group.Members.Add(new GroupMember
        {
            UserId = userId,
            Role = GroupRoleEnum.Owner
        });

        _dbContext.Groups.Add(group);
        await _dbContext.SaveChangesAsync(cancellationToken);

        return new CreateGroupResponse
        {
            Id = group.Id,
            Name = group.Name,
            JoinCode = group.JoinCode,
            Visibility = group.Visibility,
            CreatedAtUtc = group.CreatedAtUtc
        };
    }

    public async Task<IReadOnlyList<PublicGroupResponse>> GetPublicGroupsAsync(CancellationToken cancellationToken)
    {
        return await _dbContext.Groups
            .AsNoTracking()
            .Where(x => x.Visibility == GroupVisibilityEnum.Public)
            .OrderBy(x => x.Name)
            .Select(x => new PublicGroupResponse(
                x.Id,
                x.Name,
                x.Members.Count))
            .ToListAsync(cancellationToken);
    }

    public async Task<GroupDetailsResponse> GetByIdAsync(
        Guid groupId,
        Guid userId,
        CancellationToken cancellationToken)
    {
        var group = await _dbContext.Groups
            .AsNoTracking()
            .Where(x => x.Id == groupId)
            .Select(x => new
            {
                x.Id,
                x.Name,
                x.Visibility,
                x.CreatedAtUtc,
                MembersCount = x.Members.Count,
                IsMember = x.Members.Any(m => m.UserId == userId)
            })
            .SingleOrDefaultAsync(cancellationToken);

        if (group is null)
        {
            throw new KeyNotFoundException("Group not found.");
        }

        return new GroupDetailsResponse(
            group.Id,
            group.Name,
            group.Visibility,
            group.CreatedAtUtc,
            group.MembersCount,
            group.IsMember);
    }

    public async Task<IReadOnlyList<MyGroupResponse>> GetMineAsync(
        Guid userId,
        CancellationToken cancellationToken)
    {
        return await _dbContext.Groups
            .AsNoTracking()
            .Where(x => x.Members.Any(m => m.UserId == userId))
            .OrderBy(x => x.Name)
            .Select(x => new MyGroupResponse(
                x.Id,
                x.Name,
                x.Visibility,
                x.CreatedAtUtc,
                x.Members.Count))
            .ToListAsync(cancellationToken);
    }

    public async Task<JoinGroupResponse> JoinAsync(
        JoinGroupRequest request,
        Guid userId,
        CancellationToken cancellationToken)
    {
        var group = await _dbContext.Groups
            .AsNoTracking()
            .SingleOrDefaultAsync(x => x.JoinCode == request.JoinCode, cancellationToken);

        if (group is null)
        {
            throw new KeyNotFoundException("Group not found.");
        }

        var isAlreadyMember = await _dbContext.GroupMembers
            .AnyAsync(x => x.GroupId == group.Id && x.UserId == userId, cancellationToken);

        if (isAlreadyMember)
        {
            throw new InvalidOperationException("User is already a member of this group.");
        }

        if (group.Visibility != GroupVisibilityEnum.Public)
        {
            throw new InvalidOperationException("This group cannot be joined directly.");
        }

        var joinedAtUtc = DateTime.UtcNow;

        var groupMember = new GroupMember
        {
            GroupId = group.Id,
            UserId = userId,
            Role = GroupRoleEnum.User,
            JoinedAtUtc = joinedAtUtc
        };

        _dbContext.GroupMembers.Add(groupMember);
        await _dbContext.SaveChangesAsync(cancellationToken);

        return new JoinGroupResponse(group.Id, userId, joinedAtUtc);
    }

    public async Task LeaveAsync(
        Guid groupId,
        Guid userId,
        CancellationToken cancellationToken)
    {
        var membership = await _dbContext.GroupMembers
            .SingleOrDefaultAsync(x => x.GroupId == groupId && x.UserId == userId, cancellationToken);

        if (membership is null)
        {
            throw new KeyNotFoundException("Group membership not found.");
        }

        if (membership.Role == GroupRoleEnum.Owner)
        {
            throw new InvalidOperationException("Group owner cannot leave the group.");
        }

        _dbContext.GroupMembers.Remove(membership);
        await _dbContext.SaveChangesAsync(cancellationToken);
    }

    public async Task<IReadOnlyList<GroupMembersResponse>> GetMembersAsync(
        Guid groupId,
        Guid userId,
        CancellationToken cancellationToken)
    {
        var groupExists = await _dbContext.Groups
            .AsNoTracking()
            .AnyAsync(x => x.Id == groupId, cancellationToken);

        if (!groupExists)
        {
            throw new KeyNotFoundException("Group not found.");
        }

        var isMember = await _dbContext.GroupMembers
            .AnyAsync(x => x.GroupId == groupId && x.UserId == userId, cancellationToken);

        if (!isMember)
        {
            throw new UnauthorizedAccessException("User is not a member of this group.");
        }

        return await _dbContext.GroupMembers
            .AsNoTracking()
            .Where(x => x.GroupId == groupId)
            .OrderByDescending(x => x.Role)
            .ThenBy(x => x.UserId)
            .Select(x => new GroupMembersResponse(
                x.UserId,
                x.Role))
            .ToListAsync(cancellationToken);
    }

    public async Task<UpdateGroupResponse> UpdateAsync(
        Guid groupId,
        Guid userId,
        UpdateGroupRequest request,
        CancellationToken cancellationToken)
    {
        var group = await _dbContext.Groups
            .SingleOrDefaultAsync(x => x.Id == groupId, cancellationToken);

        if (group is null)
        {
            throw new KeyNotFoundException("Group not found.");
        }

        var membership = await _dbContext.GroupMembers
            .AsNoTracking()
            .SingleOrDefaultAsync(x => x.GroupId == groupId && x.UserId == userId, cancellationToken);

        if (membership is null)
        {
            throw new UnauthorizedAccessException("User is not a member of this group.");
        }

        if (membership.Role != GroupRoleEnum.Owner)
        {
            throw new UnauthorizedAccessException("Only group owner can update the group.");
        }

        group.Name = request.Name ?? group.Name;
        group.Visibility = request.Visibility ?? group.Visibility;

        await _dbContext.SaveChangesAsync(cancellationToken);

        return new UpdateGroupResponse(
            group.Id,
            group.Name,
            group.JoinCode,
            group.Visibility,
            group.CreatedAtUtc);
    }

    private async Task<string> GenerateUniqueJoinCodeAsync(CancellationToken cancellationToken)
    {
        while (true)
        {
            var code = GenerateJoinCode();

            var exists = await _dbContext.Groups
                .AnyAsync(x => x.JoinCode == code, cancellationToken);

            if (!exists)
            {
                return code;
            }
        }
    }

    private static string GenerateJoinCode()
    {
        var chars = new char[Constants.JOIN_CODE_LENGTH];

        for (var i = 0; i < chars.Length; i++)
        {
            chars[i] = Constants.JOIN_CODE_CHARS[Random.Shared.Next(Constants.JOIN_CODE_CHARS.Length)];
        }

        return new string(chars);
    }
}

