    radial-gradient(circle at top center, color-mix(in srgb, var(--accent) 14%, transparent), transparent 28%),
    radial-gradient(circle at 80% 12%, color-mix(in srgb, var(--gold) 10%, transparent), transparent 22%),
    linear-gradient(180deg, color-mix(in srgb, var(--background) 88%, #ffffff) 0%, var(--background) 42%, color-mix(in srgb, var(--background) 92%, #000000) 100%);
  color: var(--foreground);
