import { afterEach, describe, expect, it, vi } from "vitest";
import { ApiError, api } from "@/features/app/api";

describe("api client", () => {
  afterEach(() => {
    vi.unstubAllGlobals();
    vi.restoreAllMocks();
  });

  it("adds the bearer token header for authenticated requests", async () => {
    const fetchMock = vi.fn().mockResolvedValue({
      ok: true,
      status: 200,
      json: async () => ({ id: "1" }),
    });

    vi.stubGlobal("fetch", fetchMock);

    await api.get<{ id: string }>("/api/User/me", "token-123");

    expect(fetchMock).toHaveBeenCalledWith(
      "http://localhost:5016/api/User/me",
      expect.objectContaining({
        method: "GET",
        cache: "no-store",
        headers: expect.objectContaining({
          "Content-Type": "application/json",
          Authorization: "Bearer token-123",
        }),
      }),
    );
  });

  it("revives numeric enums returned by the backend", async () => {
    vi.stubGlobal(
      "fetch",
      vi.fn().mockResolvedValue({
        ok: true,
        status: 200,
        json: async () => ({
          visibility: 2,
          members: [{ role: 1 }],
        }),
      }),
    );

    const response = await api.get<{
      visibility: 0 | 1 | 2;
      members: Array<{ role: 0 | 1 | 2 }>;
    }>("/api/Groups/public");

    expect(response).toEqual({
      visibility: 2,
      members: [{ role: 1 }],
    });
  });

  it("returns undefined for 204 responses", async () => {
    vi.stubGlobal(
      "fetch",
      vi.fn().mockResolvedValue({
        ok: true,
        status: 204,
      }),
    );

    const response = await api.postWithoutResponse("/api/Groups/1/leave", "token-123");

    expect(response).toBeUndefined();
  });

  it("throws an ApiError with the backend message when the request fails", async () => {
    vi.stubGlobal(
      "fetch",
      vi.fn().mockResolvedValue({
        ok: false,
        status: 400,
        json: async () => ({ message: "Join code is invalid." }),
      }),
    );

    await expect(api.post("/api/Groups/join", { joinCode: "BAD" })).rejects.toEqual(
      new ApiError("Join code is invalid."),
    );
  });
});

import type {
  ApiMessageResponse,
  GroupRole,
  GroupVisibility,
} from "@/features/app/types";

const apiBaseUrl =
  process.env.NEXT_PUBLIC_API_URL?.replace(/\/$/, "") ?? "http://localhost:5016";

export class ApiError extends Error {}

function visibilityFromValue(value: number): GroupVisibility {
  if (value === 1 || value === 2) return value;
  return 0;
}

function roleFromValue(value: number): GroupRole {
  if (value === 1 || value === 2) return value;
  return 0;
}

function reviveEnums(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(reviveEnums);
  }

  if (value && typeof value === "object") {
    const record = value as Record<string, unknown>;
    const next: Record<string, unknown> = {};

    for (const [key, entry] of Object.entries(record)) {
      if (key === "visibility" && typeof entry === "number") {
        next[key] = visibilityFromValue(entry);
      } else if (key === "role" && typeof entry === "number") {
        next[key] = roleFromValue(entry);
      } else {
        next[key] = reviveEnums(entry);
      }
    }

    return next;
  }

  return value;
}

async function request<T>(
  path: string,
  init: RequestInit = {},
  accessToken?: string,
): Promise<T> {
  const response = await fetch(`${apiBaseUrl}${path}`, {
    ...init,
    headers: {
      "Content-Type": "application/json",
      ...(accessToken ? { Authorization: `Bearer ${accessToken}` } : {}),
      ...(init.headers ?? {}),
    },
    cache: "no-store",
  });

  if (!response.ok) {
    const maybeJson = (await response
      .json()
      .catch(() => null)) as ApiMessageResponse | null;
    throw new ApiError(
      maybeJson?.message ?? `Serwer zwrócił status ${response.status}.`,
    );
  }

  if (response.status === 204) {
    return undefined as T;
  }

  const json = (await response.json()) as unknown;
  return reviveEnums(json) as T;
}

export const api = {
  baseUrl: apiBaseUrl,
  get: <T>(path: string, accessToken?: string) =>
    request<T>(path, { method: "GET" }, accessToken),
  post: <TRequest, TResponse>(
    path: string,
    body: TRequest,
    accessToken?: string,
  ) =>
    request<TResponse>(
      path,
      { method: "POST", body: JSON.stringify(body) },
      accessToken,
    ),
  patch: <TRequest, TResponse>(
    path: string,
    body: TRequest,
    accessToken?: string,
  ) =>
    request<TResponse>(
      path,
      { method: "PATCH", body: JSON.stringify(body) },
      accessToken,
    ),
  postWithoutResponse: (path: string, accessToken?: string) =>
    request<void>(
      path,
      { method: "POST", body: JSON.stringify({}) },
      accessToken,
    ),
};

export const visibilityLabels: Record<GroupVisibility, string> = {
  0: "Public",
  1: "Private",
  2: "Friends",
};

export const roleLabels: Record<GroupRole, string> = {
  0: "User",
  1: "Admin",
  2: "Owner",
};

