                        label="Save setup"
                        onClick={() => void updateSelectedGroup()}
                        disabled={isLoadingHome}
                      />
                    </div>
                  </InfoCard>

                  <InfoCard
                    title="Grid & members"
                    eyebrow="GET /api/Groups/{groupId}/members"
                    accent="slate"
                  >
                    {selectedGroupMembers.length === 0 ? (
                      <p>
                        Brak członków do wyświetlenia albo lista jeszcze się
                        ładuje.
                      </p>
                    ) : (
